// ── getGenEdStatus ────────────────────────────────────────────────────────────
// Returns an array of three objects — one per sub-category — describing how
// many credit hours the student has filled toward the 6-hr minimum and whether
// they are at risk of being unable to meet a sub-requirement.
//
// "At risk" means the total credits still needed across all three categories
// exceeds the capacity of the remaining empty GEN_ED slots.  When the overall
// plan becomes infeasible every unsatisfied category is flagged.
//
// Archived slots are NOT capacity (BUG-54).  A slot archived by a prior credit
// is gone from the grid, so counting it as an open seat overstates how much
// room is left and silences the at-risk warning exactly when it matters most:
// a student whose prior credits saturate two sub-pools has fewer seats left
// than unarchived-slot arithmetic suggests.  Callers pass the same
// planArchived map the grid filters on.
//
// Shape: [{ category, label, filled, required, satisfied, atRisk }, ...]

const GEN_ED_CATEGORY_LABELS = {
  History:   'History',
  Humanities: 'Humanities & Arts',
  Social:    'Social Science',
}

export function getGenEdStatus(planSlots, slots, courseMap, priorCredits = [], planArchived = {}) {
  const genEdSlots  = slots.filter(
    s => s.is_pool && s.class_code === 'GEN_ED' && !planArchived?.[s.id]
  )
  const emptySlots  = genEdSlots.filter(s => !planSlots[s.id]).length

  // Build a reverse lookup: courseCode → category
  const codeToCategory = {}
  for (const [cat, codes] of Object.entries(GEN_ED_CATEGORIES)) {
    for (const code of codes) codeToCategory[code] = cat
  }

  // Sum credits per category from filled GEN_ED slots
  const creditsByCategory = { History: 0, Humanities: 0, Social: 0 }
  for (const slot of genEdSlots) {
    const code = planSlots[slot.id]
    if (!code) continue
    const cat = codeToCategory[code]
    if (cat) {
      creditsByCategory[cat] += courseMap[code]?.credits ?? 3
    }
  }

  // Sum credits per category from prior credits (BUG-45)
  for (const pc of (priorCredits ?? [])) {
    if ((pc.credits_awarded ?? 0) <= 0) continue
    if (!pc.satisfies_course_code) continue
    const cat = codeToCategory[pc.satisfies_course_code]
    if (cat) creditsByCategory[cat] += pc.credits_awarded
  }

  const REQUIRED = 6

  // Total credits still needed across all categories
  const totalShortfall = Object.values(creditsByCategory).reduce((sum, filled) => {
    return sum + Math.max(0, REQUIRED - filled)
  }, 0)

  // If the remaining empty slots can't cover the combined shortfall, every
  // unsatisfied category is at risk.
  const overallAtRisk = totalShortfall > emptySlots * 3

  return ['History', 'Humanities', 'Social'].map(cat => {
    const filled    = creditsByCategory[cat]
    const satisfied = filled >= REQUIRED
    const atRisk    = !satisfied && overallAtRisk
    return {
      category:  cat,
      label:     GEN_ED_CATEGORY_LABELS[cat],
      filled,
      required:  REQUIRED,
      satisfied,
      atRisk,
    }
  })
}

// ── formatMissingForDisplay ───────────────────────────────────────────────────
// BUG-37: Rewrites the `missing` array returned by checkPrereqs/checkCoreqs
// into a freshman-readable string.  Pool members inside an OR group collapse
// to the pool's display label so "Needs: COMM2025, PC2500" reads as
// "Needs: Communications" — codes outside any pool stay verbatim.
//
// Input shape (per prereqChecker.js):
//   - bare code:      'CSC1300'
//   - OR group:       '(A or B or C)'
//
// Rules for OR groups:
//   - For each pool that has 2+ codes in this group, replace those codes
//     with POOL_LABELS[poolCode]. A single pool member alone is NOT
//     collapsed — the prereq genuinely names that one course.
//   - Tie-break across pools: the pool with the most matching codes wins;
//     ties resolve to Object.entries iteration order on POOL_COURSES.
//   - The output OR group joins remaining tokens with ' or '.  When the
//     group reduces to a single token, drop the parentheses entirely.

export function formatMissingForDisplay(missing) {
  if (!Array.isArray(missing) || missing.length === 0) return ''
  return missing.map(formatOne).join(', ')
}

function formatOne(entry) {
  if (typeof entry !== 'string') return String(entry)
  const m = entry.match(/^\((.+)\)$/)
  if (!m) return entry                                    // bare code
  const codes = m[1].split(' or ').map(s => s.trim()).filter(Boolean)
  if (codes.length <= 1) return entry                     // malformed — leave alone

  let chosenPool    = null
  let chosenMembers = null
  for (const [poolCode, poolList] of Object.entries(POOL_COURSES)) {
    if (!Array.isArray(poolList)) continue                // skip FREE_ELECTIVE (null)
    const owned = codes.filter(c => poolList.includes(c))
    // A pool a course can depend on is the better name when two pools list the same courses (ME 4020 / ME 4720 are in both
    // Machine or Thermal Design and the Area of Emphasis list).
    const better = chosenMembers && owned.length === chosenMembers.length && REQUIREMENT_POOLS.has(poolCode) && !REQUIREMENT_POOLS.has(chosenPool)
    if (owned.length >= 2 && (!chosenMembers || owned.length > chosenMembers.length || better)) {
      chosenPool    = poolCode
      chosenMembers = owned
    }
  }

  if (!chosenPool) return entry

  const remaining = codes.filter(c => !chosenMembers.includes(c))
  const tokens    = [POOL_LABELS[chosenPool], ...remaining]
  if (tokens.length === 1) return tokens[0]
  return `(${tokens.join(' or ')})`
}

// ── getGenEdSubCategory ───────────────────────────────────────────────────────
// Returns { category, label } for any GEN_ED course code, or null if the code
// is not a GEN_ED member.  Used by SlotModal section grouping (BUG-43) and by
// PriorCreditWizard Step 4 to label which sub-pool an awarded credit fills.

export function getGenEdSubCategory(courseCode) {
  if (!courseCode) return null
  for (const [category, codes] of Object.entries(GEN_ED_CATEGORIES)) {
    if (codes.includes(courseCode)) {
      return { category, label: GEN_ED_CATEGORY_LABELS[category] }
    }
  }
  return null
}

// ── resolveFreeElective ───────────────────────────────────────────────────────

export function resolveFreeElective(courseMap, slots, planSlots) {
  const planSubjectCodes = new Set()

  slots
    .filter(s => !s.is_pool)
    .forEach(s => {
      const course = courseMap[s.class_code]
      if (course) planSubjectCodes.add(course.subject_code)
    })

  Object.values(planSlots).forEach(code => {
    const course = courseMap[code]
    if (course) planSubjectCodes.add(course.subject_code)
  })

  const allCourses = Object.values(courseMap)

  const suggested = allCourses
    .filter(c => planSubjectCodes.has(c.subject_code))
    .sort((a, b) => a.code.localeCompare(b.code))

  const other = allCourses
    .filter(c => !planSubjectCodes.has(c.subject_code))
    .sort((a, b) => a.code.localeCompare(b.code))

  return { suggested, other }
}

// Drops courses already planned or taken (a Set of codes) from a
// resolveFreeElective result. A free elective can't repeat a course the plan
// already holds; the picker hides them rather than greying them out.
export function excludeFreeElectiveCodes({ suggested, other }, excludeCodes) {
  const keep = c => !excludeCodes.has(c.code)
  return { suggested: suggested.filter(keep), other: other.filter(keep) }
}